"""Original general-examination questions emphasizing interpretation and limitations."""
from qbank_authoring import question,ref
rows=[]
CM=ref('Clinical Methods: history, physical and laboratory examination','https://www.ncbi.nlm.nih.gov/books/NBK201/')
HA=ref('Stanford Medicine 25: the hand examination','https://stanfordmedicine25.stanford.edu/the25/hand.html')
CY=ref('Clinical Methods: cyanosis','https://www.ncbi.nlm.nih.gov/books/NBK367/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A patient has pale conjunctivae and palms. Which inference is appropriate before the blood count returns?', 'Anemia is possible, but pallor cannot determine the hemoglobin concentration or cause reliably',[
 ('Pallor establishes iron deficiency specifically','Other anemias and nonhematological factors can produce pallor.'),('The examination provides an exact hemoglobin estimate','Clinical grading is too imprecise for that purpose.'),('Absence of pallor would exclude clinically important anemia','Sensitivity is limited and examination conditions matter.')],
 'Use pallor as a clue rather than a quantitative assay','**Lighting, pigmentation and perfusion affect its appearance.**',['Examine appropriate mucosal and skin sites.','Interpret symptoms and other signs together.'],'**Confirm with a blood count and investigate the mechanism.**',['Assess bleeding, hemolysis, production failure and nutritional clues.','Do not infer a specific deficiency from pallor alone.'],[['Sign','Possible anemia'],['Limit','No exact concentration'],['Next step','CBC and cause assessment']],[CM],style='clinical_scenario')

q('Which examination finding most strongly supports central rather than isolated peripheral cyanosis?', 'Bluish discoloration involving the tongue and oral mucosa',[
 ('Blue cold fingertips with a pink tongue','This favors a peripheral circulation/extraction contribution.'),('A prolonged capillary refill alone','This suggests impaired peripheral perfusion, not specifically central desaturation.'),('Dependent ankle edema alone','This does not establish the mechanism of cyanosis.')],
 'Inspect mucosa as well as extremities','**Central cyanosis reflects arterial desaturation or abnormal hemoglobin species in the appropriate context.**',['Peripheral cyanosis can result from increased extraction in slow/cold circulation.','The two can coexist.'],'**Measure oxygenation and investigate the cause.**',['Use co-oximetry if dyshemoglobinemia is suspected.','Appearance is affected by hemoglobin concentration and examination conditions.'],[['Central','Tongue/mucosa involved'],['Peripheral','Often cold extremities'],['Confirmation','Oxygenation/hemoglobin-species assessment']],[CY])

q('Why can severe arterial desaturation be less visibly cyanotic in marked anemia than in polycythemia?', 'Visible cyanosis depends partly on the absolute amount of deoxygenated hemoglobin, not saturation alone',[
 ('Anemia prevents tissue hypoxia at any saturation','Low hemoglobin can worsen oxygen delivery.'),('Polycythemia guarantees adequate oxygen delivery despite cyanosis','Delivery also depends on saturation, flow and viscosity.'),('Skin color directly measures PaO2 independently of hemoglobin','Appearance does not provide a direct oxygen-tension measurement.')],
 'A color sign is not a complete oxygen-transport assessment','**The same saturation can produce different visible findings at different hemoglobin levels.**',['Lighting and observer factors further limit detection.','Do not use absence of cyanosis to exclude hypoxemia.'],'**Use objective oxygenation and hemoglobin measurements.**',['Assess perfusion and symptoms.','Consider abnormal hemoglobin species when the measurements disagree.'],[['Saturation','Fractional oxygenation'],['Hemoglobin','Changes absolute deoxyhemoglobin'],['Clinical limit','No cyanosis does not exclude danger']],[CY])

q('Loss of the normal nail-fold angle with a positive Schamroth-window finding supports which sign?', 'Digital clubbing',[
 ('Koilonychia','This produces spoon-shaped nails rather than the characteristic clubbing geometry.'),('Onycholysis','This is separation of the nail plate from the bed.'),('Splinter hemorrhages','These are linear subungual hemorrhagic lesions.')],
 'Define the morphology before naming a cause','**Clubbing alters the distal digit and nail-bed relationship.**',['Nail-bed fluctuation and distal phalangeal enlargement can support assessment.','Familial and acquired causes exist.'],'**Investigate a new acquired sign in the clinical context.**',['Consider pulmonary, cardiac, GI/hepatic and other causes.','Clubbing does not identify one diagnosis by itself.'],[['Angle/window','Altered in clubbing'],['Koilonychia','Concave spoon nail'],['Splinters','Linear hemorrhage']],[HA])

q('A patient labeled as having uncomplicated COPD develops new marked clubbing. What is the most appropriate interpretation?', 'Look for an additional cause such as lung malignancy, bronchiectasis or interstitial disease',[
 ('Clubbing is an expected defining feature of uncomplicated COPD','It should prompt assessment for another process.'),('The sign specifically proves cyanotic congenital heart disease','Several acquired conditions can cause clubbing.'),('No further assessment is needed if spirometry shows obstruction','Obstruction does not explain every new examination finding.')],
 'Do not let an existing diagnosis absorb a discordant sign','**New clubbing requires a context-based cause search.**',['Review cough, hemoptysis, constitutional symptoms and imaging.','Hypertrophic osteoarthropathy may add bone/joint findings.'],'**Choose investigations according to the whole presentation.**',['Do not diagnose cancer from clubbing alone.','Document whether the finding is longstanding or familial.'],[['Existing COPD','Does not explain new clubbing by itself'],['Differential','Malignancy/bronchiectasis/ILD and others'],['Action','Targeted assessment']],[HA],style='clinical_scenario')

q('Spoon-shaped nails are found in a patient with fatigue. Which association is worth investigating without treating the sign as diagnostic?', 'Iron deficiency',[
 ('Acute hyperkalemia as the defining cause','This is not the characteristic association.'),('Vitamin B12 deficiency as uniquely established by the nail shape','The sign is not specific for that diagnosis.'),('A requirement for infective endocarditis','Koilonychia is not a defining endocarditis sign.')],
 'Morphology suggests a differential rather than proving an etiology','**Koilonychia is associated with iron deficiency but also has other causes.**',['Review occupational, local and longstanding changes.','Symptoms and blood indices guide the workup.'],'**Confirm deficiency before treating and identify its cause.**',['Assess dietary, bleeding and malabsorption possibilities.','Do not use nail appearance as the sole treatment endpoint.'],[['Morphology','Spoon nail'],['Association','Iron deficiency'],['Confirmation','Laboratory and cause assessment']],[HA],style='clinical_scenario')

q('A patient has palmar erythema and several spider angiomas. Which interpretation is most accurate?', 'These can support chronic liver disease in context but are not specific and can occur in other states',[
 ('They establish cirrhosis without further evidence','Specificity is insufficient.'),('They are impossible in pregnancy','Physiological hormonal states can produce similar signs.'),('They quantify portal pressure accurately','They do not provide a pressure measurement.')],
 'Combine peripheral signs with organ and functional evidence','**Vascular skin findings are supportive rather than definitive.**',['Review alcohol, medication, endocrine and physiological contexts.','Look for jaundice, ascites, splenomegaly and synthetic dysfunction.'],'**Confirm the suspected disease with appropriate testing.**',['Assess severity separately from the number of skin lesions.','Avoid labeling chronic liver failure from one sign.'],[['Supportive signs','Palmar erythema/spiders'],['Specificity','Limited'],['Diagnosis','Integrated assessment']],[CM],style='clinical_scenario')

q('What is the appropriate implication of xanthelasma on general examination?', 'Assess cardiovascular and lipid risk, recognizing that serum lipids may be normal',[
 ('It proves familial hypercholesterolemia in every patient','The finding is not that specific.'),('It excludes a lipid disorder because the lesion is superficial','It can be associated with dyslipidemia.'),('It gives an exact LDL concentration','Physical appearance cannot quantify LDL.')],
 'A visible lipid-associated sign can prompt risk assessment','**Xanthelasma and tendon xanthomas have different diagnostic implications.**',['Tendon xanthomas are a stronger clue to inherited lipid disorders in the right setting.','Family and premature-vascular history matter.'],'**Measure lipids and assess the overall phenotype.**',['Do not assume one skin lesion establishes a genetic diagnosis.','Address modifiable vascular risk according to the results.'],[['Xanthelasma','May occur with normal lipids'],['Tendon xanthoma','Stronger inherited-lipid clue'],['Next step','Lipid/vascular assessment']],[CM])

q('A persistent hard left supraclavicular node is found in an adult with weight loss. Which approach is most appropriate?', 'Prompt evaluation for malignancy and other causes with appropriate tissue diagnosis',[
 ('Diagnose gastric cancer as certain from node location alone','The drainage pattern suggests a differential but is not uniquely diagnostic.'),('Reassure because supraclavicular nodes are normally enlarged','Persistent enlargement at this site is concerning.'),('Use repeated empirical steroids before establishing the cause','This can obscure diagnoses such as lymphoma.')],
 'Location and consistency alter concern, not certainty','**Supraclavicular lymphadenopathy can reflect thoracic or abdominal disease.**',['Age, duration, tenderness and systemic findings guide urgency.','Infection and other causes remain possible.'],'**Plan imaging and sampling based on the clinical pattern.**',['Select a biopsy approach that preserves diagnostic information when lymphoma is possible.','Avoid delaying evaluation through repeated unstructured treatment.'],[['Site','Supraclavicular'],['Red flags','Hard/persistent/weight loss'],['Diagnosis','Requires cause investigation/tissue when indicated']],[CM],style='clinical_scenario')

q('What is generally meant by generalized lymphadenopathy?', 'Enlargement in at least two noncontiguous lymph-node regions',[
 ('Several nodes within one cervical chain only','That remains a localized regional pattern.'),('Any single node larger than 1 cm regardless of location','Size alone does not define generalized distribution.'),('Only simultaneous liver and spleen enlargement','Hepatosplenomegaly is a separate finding.')],
 'Distribution changes the differential','**A generalized pattern suggests a systemic process.**',['Infection, immune disease, drugs and hematological malignancy are possibilities.','Size thresholds and normal findings vary by site and age.'],'**Examine the full accessible nodal system and related organs.**',['Record consistency, mobility, tenderness and skin changes.','Use history and testing to identify the cause rather than treating distribution as a diagnosis.'],[['Localized','One regional basin'],['Generalized','Noncontiguous regions'],['Systemic clues','Fever, rash, organomegaly and blood findings']],[CM])
